import React from 'react';
import ReactDOM from 'react-dom';
import './index.css';
import { PRODUCTS, TYPES, SUMMARY_TYPES } from './products';

// wenn mit if, geht es offline nicht mehr.
//  if ('serviceWorker' in navigator) {
navigator.serviceWorker.register('service-worker.js');
// }

// Rabatt-Buttons neben der Summe (in Prozent)
const DISCOUNTS = [10, 30];

const euro = value =>
  value.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });

// ---------------------------------------------------------------------------
// Anzeige-Komponenten
// ---------------------------------------------------------------------------

function Square(props) {
  return (
    <div className="product">
      <div className="name" onClick={props.onClick}>{props.name}</div>
      <div className="count">{props.count}</div>
      <div className="size" onClick={props.onClick}>{props.size}</div>
      <div className="price" onClick={props.onClick}>{euro(props.price)}</div>
      <button className="minus" onClick={props.onMinusClick}>-</button>
    </div>
  );
}

function HandSquare(props) {
  return (
    <div className="product">
      <div className="name">{props.name}</div>
      <input
        type="number"
        className="price"
        id={props.name}
        min="0"
        max="100"
        value={props.input}
        onChange={props.onChange}
      />
      <button className="minus" onClick={props.onMinusClick}>-</button>
    </div>
  );
}

function Spacer(props) {
  return <div className="product">{props.name}</div>;
}

function Board(props) {
  const visible = PRODUCTS.filter(p => p.type === props.currentChoose);
  return (
    <div>
      <div className="board-row">
        {visible.map(p => {
          if (p.spacer) {
            return <div key={p.id}><Spacer name={p.name} /></div>;
          }
          if (p.type === 'Hand') {
            return (
              <div key={p.id}>
                <HandSquare
                  name={p.name}
                  input={props.handInput[p.id] || ''}
                  onChange={e => props.onHandChange(p.id, e.target.value)}
                  onMinusClick={() => props.onHandReset(p.id)}
                />
              </div>
            );
          }
          return (
            <div key={p.id}>
              <Square
                name={p.name}
                size={p.size}
                price={p.price}
                count={props.counts[p.id] || 0}
                onClick={() => props.onAdd(p.id)}
                onMinusClick={() => props.onRemove(p.id)}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

function Choose(props) {
  return (
    <div>
      <div className="chooseBox">
        {TYPES.map(type => (
          <button
            key={type}
            className="choose"
            onClick={() => props.onClick(type)}
          >
            {type}
          </button>
        ))}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Berechnung
// ---------------------------------------------------------------------------

// Preis eines Produkts; bei 'Hand' kommt er aus dem Eingabefeld.
function priceOf(product, handInput) {
  if (product.type === 'Hand') {
    return parseFloat(handInput[product.id]) || 0;
  }
  return product.price;
}

// Summe in Cent gerechnet, damit keine Rundungsfehler entstehen.
// discount = Rabatt in Prozent (0, 10, 30 ...), wird auf die Gesamtsumme gerechnet.
function calculateSum(counts, handInput, discount) {
  const cents = PRODUCTS.reduce((acc, p) => {
    if (p.spacer) return acc;
    const count = counts[p.id] || 0;
    return acc + count * Math.round(priceOf(p, handInput) * 100);
  }, 0);
  return Math.round(cents * (100 - discount) / 100) / 100;
}

function calculateCount(counts, type) {
  return PRODUCTS
    .filter(p => p.type === type)
    .reduce((acc, p) => acc + (counts[p.id] || 0), 0);
}

// ---------------------------------------------------------------------------
// Kasse
// ---------------------------------------------------------------------------

class Game extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      counts: {},      // { produktId: Anzahl }
      handInput: {},   // { produktId: eingetippter Text } für Kategorie 'Hand'
      currentChoose: 'Brot',
      discount: 0,     // Rabatt in Prozent, 0 = kein Rabatt
    };
  }

  handleChooseClick = type => {
    this.setState({ currentChoose: type });
  };

  handleAdd = id => {
    this.setState(state => ({
      counts: { ...state.counts, [id]: (state.counts[id] || 0) + 1 },
    }));
  };

  handleRemove = id => {
    this.setState(state => ({
      counts: { ...state.counts, [id]: Math.max(0, (state.counts[id] || 0) - 1) },
    }));
  };

  // Eingabe bei 'Hand': Text merken, Anzahl ist immer 1
  handleHandChange = (id, value) => {
    this.setState(state => ({
      handInput: { ...state.handInput, [id]: value },
      counts: { ...state.counts, [id]: 1 },
    }));
  };

  // Minus bei 'Hand': Preis und Anzahl zurücksetzen
  handleHandReset = id => {
    this.setState(state => ({
      handInput: { ...state.handInput, [id]: '' },
      counts: { ...state.counts, [id]: 0 },
    }));
  };

  // Rabatt-Button: nochmal antippen schaltet den Rabatt wieder aus
  handleDiscount = percent => {
    this.setState(state => ({
      discount: state.discount === percent ? 0 : percent,
    }));
  };

  // "C": alles zurücksetzen (auch den Rabatt), ausgewählte Kategorie bleibt
  handleClear = () => {
    this.setState({ counts: {}, handInput: {}, discount: 0 });
  };

  render() {
    const { counts, handInput, currentChoose, discount } = this.state;
    const summe = calculateSum(counts, handInput, discount);

    return (
      <div className="game">
        <Choose onClick={this.handleChooseClick} />

        <div className="game-board">
          <Board
            counts={counts}
            handInput={handInput}
            currentChoose={currentChoose}
            onAdd={this.handleAdd}
            onRemove={this.handleRemove}
            onHandChange={this.handleHandChange}
            onHandReset={this.handleHandReset}
          />
        </div>

        <div className="game-info">
          <div className="info-left">
            <div className="zahl">
              {SUMMARY_TYPES
                .map(type => `${type}: ${calculateCount(counts, type)}`)
                .join(', ')}
            </div>
            <div className="sum-row">
              <div className="sum">Summe: {euro(summe)}</div>
              {DISCOUNTS.map(percent => (
                <button
                  key={percent}
                  className={'discount' + (discount === percent ? ' active' : '')}
                  onClick={() => this.handleDiscount(percent)}
                >
                  {percent}%
                </button>
              ))}
            </div>
          </div>
          <div className="info-right">
            <button className="button" onClick={this.handleClear}>C</button>
          </div>
        </div>
      </div>
    );
  }
}

// ========================================

ReactDOM.render(<Game />, document.getElementById('root'));
